            /** Format: date-time */
            connected_at: string;
            /** Format: uuid */
            id: string;
            import: components["schemas"]["AccountingImport"];
            last_error?: string | null;
            /** Format: date-time */
            last_error_at?: string | null;
            /** Format: date-time */
            last_synced_at?: string | null;
